CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, username TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at BIGINT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS journeys (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, description TEXT NOT NULL, destination TEXT NOT NULL, meeting_point TEXT, status TEXT NOT NULL, created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS participants (journey_id TEXT NOT NULL REFERENCES journeys(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL, status TEXT NOT NULL, mode TEXT NOT NULL, delay_minutes INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(journey_id,user_id));
CREATE TABLE IF NOT EXISTS invitations (hash TEXT PRIMARY KEY, journey_id TEXT NOT NULL REFERENCES journeys(id) ON DELETE CASCADE, inviter_id TEXT NOT NULL REFERENCES users(id), target_id TEXT REFERENCES users(id), expires_at BIGINT NOT NULL, used_at BIGINT);
CREATE TABLE IF NOT EXISTS grants (journey_id TEXT NOT NULL, user_id TEXT NOT NULL, mode TEXT NOT NULL, viewers TEXT NOT NULL, allow_meeting INTEGER NOT NULL DEFAULT 0, expires_at BIGINT NOT NULL, PRIMARY KEY(journey_id,user_id), FOREIGN KEY(journey_id,user_id) REFERENCES participants(journey_id,user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS live_locations (journey_id TEXT NOT NULL, user_id TEXT NOT NULL, latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL, accuracy DOUBLE PRECISION NOT NULL, timestamp BIGINT NOT NULL, PRIMARY KEY(journey_id,user_id), FOREIGN KEY(journey_id,user_id) REFERENCES grants(journey_id,user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS etas (journey_id TEXT NOT NULL, user_id TEXT NOT NULL, arrival BIGINT NOT NULL, calculated_at BIGINT NOT NULL, source TEXT NOT NULL, PRIMARY KEY(journey_id,user_id), FOREIGN KEY(journey_id,user_id) REFERENCES participants(journey_id,user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, journey_id TEXT NOT NULL REFERENCES journeys(id) ON DELETE CASCADE, sender_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS proposals (id TEXT PRIMARY KEY, journey_id TEXT NOT NULL REFERENCES journeys(id) ON DELETE CASCADE, proposer TEXT NOT NULL REFERENCES users(id), place TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS blocks (owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, target_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(owner_id,target_id));
CREATE TABLE IF NOT EXISTS friendships (id TEXT PRIMARY KEY, sender_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, target_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL, created_at BIGINT NOT NULL, UNIQUE(sender_id,target_id));
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, reporter_id TEXT NOT NULL REFERENCES users(id), target_id TEXT NOT NULL REFERENCES users(id), reason TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS saved_places (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, place TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS grants_expiry ON grants(expires_at);
CREATE INDEX IF NOT EXISTS invitations_expiry ON invitations(expires_at);
CREATE INDEX IF NOT EXISTS participant_user ON participants(user_id);
CREATE INDEX IF NOT EXISTS messages_room ON messages(journey_id,created_at);
